import * as THREE from 'three';

// Deterministic PRNG (mulberry32) so a given seed always produces the
// exact same simulation.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const MAX_SPEED = 1.2;
const DAMPING = 0.98;          // per-step velocity damping
const JITTER_ACCEL = 2.5;      // seeded random-walk acceleration amplitude
const SPRING_K = 12;           // soft-bounds spring strength

/**
 * Creates a firefly swarm: typed arrays + a THREE.Points object.
 */
export function createFireflies({ count = 60, bounds = 8, seed = 1 } = {}) {
  const positions = new Float32Array(count * 3);
  const velocities = new Float32Array(count * 3);
  const blinkPhase = new Float32Array(count);
  const periods = new Float64Array(count);

  const rand = mulberry32(seed);

  for (let i = 0; i < count; i++) {
    const ix = i * 3;
    positions[ix] = (rand() * 2 - 1) * bounds * 0.5;
    positions[ix + 1] = (rand() * 2 - 1) * bounds * 0.5;
    positions[ix + 2] = (rand() * 2 - 1) * bounds * 0.5;

    blinkPhase[i] = rand() * Math.PI * 2;
    periods[i] = 1.5 + rand() * 1.5;
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const material = new THREE.PointsMaterial({
    color: 0xc8ff8a,
    size: 0.18,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;

  return {
    count,
    bounds,
    seed,
    positions,
    velocities,
    blinkPhase,
    periods,
    points,
    _rand: rand,
  };
}

/**
 * Advances the swarm by dt seconds:
 * - velocity += seeded jitter (random walk, deterministic per seed)
 * - velocity *= 0.98 damping
 * - speed capped at MAX_SPEED
 * - soft spring pulls fireflies back when |coord| > bounds
 *
 * Allocates nothing; mutates the typed arrays in place.
 */
export function stepFireflies(f, dt) {
  const { positions, velocities, count, bounds } = f;
  const rand = f._rand;
  const maxSpeedSq = MAX_SPEED * MAX_SPEED;
  const jitterScale = JITTER_ACCEL * dt;

  for (let i = 0; i < count; i++) {
    const ix = i * 3;

    // Seeded random-walk jitter
    velocities[ix] += (rand() * 2 - 1) * jitterScale;
    velocities[ix + 1] += (rand() * 2 - 1) * jitterScale;
    velocities[ix + 2] += (rand() * 2 - 1) * jitterScale;

    // Soft bounds: spring proportional to penetration beyond |coord| > bounds
    let p = positions[ix];
    if (p > bounds) velocities[ix] -= SPRING_K * (p - bounds) * dt;
    else if (p < -bounds) velocities[ix] -= SPRING_K * (p + bounds) * dt;
    p = positions[ix + 1];
    if (p > bounds) velocities[ix + 1] -= SPRING_K * (p - bounds) * dt;
    else if (p < -bounds) velocities[ix + 1] -= SPRING_K * (p + bounds) * dt;
    p = positions[ix + 2];
    if (p > bounds) velocities[ix + 2] -= SPRING_K * (p - bounds) * dt;
    else if (p < -bounds) velocities[ix + 2] -= SPRING_K * (p + bounds) * dt;

    // Damping
    let vx = velocities[ix] * DAMPING;
    let vy = velocities[ix + 1] * DAMPING;
    let vz = velocities[ix + 2] * DAMPING;

    // Speed cap
    const speedSq = vx * vx + vy * vy + vz * vz;
    if (speedSq > maxSpeedSq) {
      const s = MAX_SPEED / Math.sqrt(speedSq);
      vx *= s;
      vy *= s;
      vz *= s;
    }
    velocities[ix] = vx;
    velocities[ix + 1] = vy;
    velocities[ix + 2] = vz;

    // Integrate
    positions[ix] += vx * dt;
    positions[ix + 1] += vy * dt;
    positions[ix + 2] += vz * dt;
  }

  // Keep the GPU-side attribute in sync for rendering.
  const attr = f.points.geometry.getAttribute('position');
  if (attr && attr.array === positions) attr.needsUpdate = true;
}

/**
 * Per-firefly blink brightness in [0, 1]:
 *   0.5 + 0.5*sin(2*PI*t/period_i + phase_i)
 */
export function brightness(f, i, t) {
  return 0.5 + 0.5 * Math.sin((2 * Math.PI * t) / f.periods[i] + f.blinkPhase[i]);
}

