import { describe, it, expect } from 'vitest';
import { createFireflies, stepFireflies, brightness } from '../src/fireflies.js';

const DT = 1 / 60;

function runSteps(f, n, dt = DT) {
  for (let s = 0; s < n; s++) stepFireflies(f, dt);
}

describe('createFireflies', () => {
  it('exposes typed arrays and a Points object', () => {
    const f = createFireflies({ count: 60, bounds: 8, seed: 42 });
    expect(f.positions).toBeInstanceOf(Float32Array);
    expect(f.velocities).toBeInstanceOf(Float32Array);
    expect(f.blinkPhase).toBeInstanceOf(Float32Array);
    expect(f.positions.length).toBe(180);
    expect(f.velocities.length).toBe(180);
    expect(f.blinkPhase.length).toBe(60);
    expect(f.points.isPoints).toBe(true);
  });

  it('seeds periods in [1.5, 3]', () => {
    const f = createFireflies({ count: 200, seed: 7 });
    for (let i = 0; i < f.count; i++) {
      expect(f.periods[i]).toBeGreaterThanOrEqual(1.5);
      expect(f.periods[i]).toBeLessThanOrEqual(3);
    }
  });
});

describe('soft bounds', () => {
  it('keeps all positions within bounds + 1 after 3000 steps of 1/60', () => {
    const f = createFireflies({ count: 60, bounds: 8, seed: 1234 });
    runSteps(f, 3000);
    const limit = f.bounds + 1;
    for (let k = 0; k < f.positions.length; k++) {
      expect(Math.abs(f.positions[k])).toBeLessThanOrEqual(limit);
    }
  });
});

describe('speed cap', () => {
  it('never lets speeds exceed 1.2 + 1e-9', () => {
    const f = createFireflies({ count: 60, bounds: 8, seed: 99 });
    for (let s = 0; s < 3000; s++) {
      stepFireflies(f, DT);
      for (let i = 0; i < f.count; i++) {
        const ix = i * 3;
        const vx = f.velocities[ix];
        const vy = f.velocities[ix + 1];
        const vz = f.velocities[ix + 2];
        expect(Math.sqrt(vx * vx + vy * vy + vz * vz)).toBeLessThanOrEqual(
          1.2 + 1e-9
        );
      }
    }
  });
});

describe('brightness', () => {
  it('stays in [0, 1]', () => {
    const f = createFireflies({ count: 60, seed: 5 });
    for (let i = 0; i < f.count; i++) {
      for (let t = 0; t <= 10; t += 0.037) {
        const b = brightness(f, i, t);
        expect(b).toBeGreaterThanOrEqual(0);
        expect(b).toBeLessThanOrEqual(1);
      }
    }
  });

  it('is periodic with period_i (within 1e-9)', () => {
    const f = createFireflies({ count: 60, seed: 11 });
    for (let i = 0; i < f.count; i++) {
      for (let t = 0; t <= 25; t += 0.61) {
        const a = brightness(f, i, t);
        const b = brightness(f, i, t + f.periods[i]);
        expect(Math.abs(a - b)).toBeLessThanOrEqual(1e-9);
      }
    }
  });
});

describe('determinism', () => {
  it('two runs with the same seed match exactly', () => {
    const a = createFireflies({ count: 60, bounds: 8, seed: 777 });
    const b = createFireflies({ count: 60, bounds: 8, seed: 777 });
    runSteps(a, 1000);
    runSteps(b, 1000);
    expect(a.positions).toEqual(b.positions);
    expect(a.velocities).toEqual(b.velocities);
  });

  it('two different seeds diverge', () => {
    const a = createFireflies({ count: 60, bounds: 8, seed: 1 });
    const b = createFireflies({ count: 60, bounds: 8, seed: 2 });
    runSteps(a, 1000);
    runSteps(b, 1000);
    let same = true;
    for (let k = 0; k < a.positions.length; k++) {
      if (a.positions[k] !== b.positions[k]) {
        same = false;
        break;
      }
    }
    expect(same).toBe(false);
  });
});

describe('allocation-free stepping', () => {
  it('stepFireflies keeps the exact same array objects', () => {
    const f = createFireflies({ count: 60, bounds: 8, seed: 2024 });
    const posBefore = f.positions;
    const velBefore = f.velocities;
    const phaseBefore = f.blinkPhase;
    const periodsBefore = f.periods;
    runSteps(f, 10);
    expect(f.positions).toBe(posBefore);
    expect(f.velocities).toBe(velBefore);
    expect(f.blinkPhase).toBe(phaseBefore);
    expect(f.periods).toBe(periodsBefore);
  });
});

